<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import WorkspaceSidebar from '@/Components/WorkspaceSidebar.vue';
import { Head } from '@inertiajs/vue3';
import { ref } from 'vue';
const props=defineProps({savedSummaries:{type:Array,default:()=>[]}});
const transcript=ref('');
const summary=ref(null);
const processing=ref(false);
const error=ref('');
const submit=async()=>{processing.value=true;error.value='';summary.value=null;try{const response=await window.axios.post(route('summaries.store'),{transcript:transcript.value});summary.value=response.data;}catch(e){error.value=e.response?.data?.message||'Summary request failed.';}finally{processing.value=false;}};
</script>
<template>
<Head title="AI summaries"/><AuthenticatedLayout><div class="min-h-screen bg-[#f6f7fb]"><div class="mx-auto grid max-w-[1440px] gap-6 px-4 py-6 sm:px-6 lg:grid-cols-[230px_minmax(0,1fr)] lg:gap-8 lg:px-10 lg:py-9"><WorkspaceSidebar/><main class="min-w-0 space-y-6">
<header><p class="text-sm text-slate-400">Meeting intelligence</p><h1 class="mt-1 text-3xl font-bold text-slate-900">AI summaries</h1><p class="mt-2 text-sm text-slate-500">Submit a transcript to Laravel for provider-backed summarization.</p></header>
<div class="grid gap-5 xl:grid-cols-[minmax(0,1fr)_320px]"><section class="space-y-5"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><h2 class="font-bold text-slate-900">Summarize a transcript</h2><p class="mt-1 text-sm text-slate-500">Your transcript is stored in MySQL and processed when an AI provider is configured.</p><label for="transcript" class="mb-2 mt-6 block text-sm font-semibold text-slate-700">Transcript</label><textarea id="transcript" v-model="transcript" rows="9" maxlength="100000" placeholder="Paste your transcript here…" class="w-full rounded-xl border-slate-200 bg-slate-50 text-sm leading-6 focus:border-indigo-500 focus:ring-indigo-500"></textarea><div class="mt-4 flex items-center justify-between"><span class="text-xs text-slate-400">{{transcript.length}} characters</span><button @click="submit" :disabled="processing||transcript.trim().length<20" class="rounded-xl bg-indigo-600 px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">{{processing?'Working…':'Generate summary'}}</button></div></article>
<article v-if="summary" class="rounded-2xl border border-indigo-100 bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wider text-indigo-600">{{summary.status}}</p><h2 class="mt-1 text-lg font-bold text-slate-900">Meeting summary</h2><p class="mt-3 text-sm leading-6 text-slate-600">{{summary.summary||summary.message}}</p><div v-if="summary.summary" class="mt-5 grid gap-5 sm:grid-cols-2"><div><h3 class="text-sm font-bold">Key decisions</h3><ul class="mt-2 list-inside list-disc text-sm text-slate-500"><li v-for="item in summary.decisions" :key="item">{{item}}</li></ul></div><div><h3 class="text-sm font-bold">Action items</h3><ul class="mt-2 list-inside list-disc text-sm text-slate-500"><li v-for="item in summary.action_items" :key="item">{{item}}</li></ul></div></div></article><p v-if="error" class="rounded-xl bg-rose-50 p-4 text-sm text-rose-700">{{error}}</p></section>
<section v-if="savedSummaries.length" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-bold text-slate-900">Saved summaries</h2><article v-for="item in savedSummaries" :key="item.id" class="mt-4 border-t border-slate-100 pt-4"><div class="flex items-center justify-between gap-3"><p class="font-semibold text-slate-800">{{item.summary || 'Transcript saved'}}</p><span class="rounded-full bg-slate-100 px-2 py-1 text-xs text-slate-500">{{item.status}}</span></div><p class="mt-1 text-xs text-slate-400">{{new Date(item.created_at).toLocaleString()}}</p><div v-if="item.action_items?.length" class="mt-2 text-sm text-slate-600">Action items: {{item.action_items.join(' · ')}}</div></article></section><aside class="space-y-4"><section class="rounded-2xl bg-indigo-600 p-5 text-white"><span class="text-xl">✧</span><h3 class="mt-3 font-bold">Transcript workflow</h3><p class="mt-2 text-sm leading-6 text-indigo-100">Laravel checks your plan, stores the transcript, then sends it to your configured AI provider.</p></section><section class="rounded-2xl border border-slate-200 bg-white p-5"><h3 class="font-semibold text-slate-800">Setup required</h3><p class="mt-2 text-sm leading-6 text-slate-500">Configure AI_SUMMARY_URL and AI_SUMMARY_KEY in the server environment to enable generated summaries.</p></section></aside></div>
</main></div></div></AuthenticatedLayout></template>
